INSERT INTO `artists` (`artist_id`, `artist_name`, `artist_intro`, `intro_source_url`, `intro_updated_at`, `created_at`, `updated_at`) VALUES
('1','鄧麗君','鄧麗君，本名鄧麗筠，臺灣女歌手、演員及慈善家。她是20世紀後期華語流行音樂極具代表性的人物，也是當代華語音樂的先驅之一。時至今日，鄧麗君仍被視為全球華人地區流行文化的代表人物之一。','https://zh.wikipedia.org/wiki/%E9%84%A7%E9%BA%97%E5%90%9B','2026-04-27 17:14:38','2026-04-27 17:14:14','2026-04-27 17:14:38'),
('2','MIKA NAKASHIMA','中島美嘉 是日本歌手與演員，鹿兒島縣日置市伊集院町出身，所屬經紀公司為True Project，所屬唱片公司則為日本索尼音樂娛樂。','https://zh.wikipedia.org/wiki/%E4%B8%AD%E5%B3%B6%E7%BE%8E%E5%98%89','2026-04-27 17:14:40','2026-04-27 17:14:14','2026-04-27 17:14:40'),
('3','沈文程','沈文程（1954年6月6日—），本名周沈文程，臺灣男演員、主持人及歌手，是金曲獎和金鐘獎的得主，畢業於空軍機械學校（今空軍航空技術學院）。','https://zh.wikipedia.org/wiki/%E6%B2%88%E6%96%87%E7%A8%8B','2026-04-27 17:14:42','2026-04-27 17:14:14','2026-04-27 17:14:42'),
('4','木與銅的對話-林子葇與黃芝庭聯合','木與銅的對話-林子葇與黃芝庭聯合 為本資料庫收錄之演出藝人，後續將持續補充完整介紹。',NULL,'2026-04-27 17:35:40','2026-04-27 17:14:14','2026-04-27 17:35:40'),
