INSERT INTO `venues` (`venue_id`, `venue_name`, `venue_address`, `venue_intro`, `intro_source_url`, `intro_updated_at`, `created_at`, `updated_at`) VALUES
('1','高雄流行音樂中心 海音館','未提供','高雄流行音樂中心，為高雄市政府文化局轄下的表演場館暨行政法人，原興建計畫名稱海洋文化及流行音樂中心，基地位於高雄港11-15號碼頭（真愛碼頭、光榮碼頭及苓雅寮車場），占地約11.89公頃，於2021年正式啟用。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-27 17:22:23','2026-04-27 17:14:14','2026-04-27 17:22:23'),
('2','高雄市音樂館演奏廳','未提供','高雄市音樂館位於高雄市鹽埕區，成立於西元2000年11月，與高雄市立歷史博物館並立於愛河旁。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E9%9F%B3%E6%A8%82%E9%A4%A8','2026-04-27 17:22:25','2026-04-27 17:14:14','2026-04-27 17:22:25'),
('3','台北流行音樂中心表演廳','未提供','臺北流行音樂中心 是臺北市成立的第一個行政法人，位於台灣臺北市南港區的流行音樂園區。園區內包括表演廳、流行音樂文化館、產業區及戶外開放空間。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-27 17:22:27','2026-04-27 17:14:14','2026-04-27 17:22:27'),
('4','台北國際會議中心大會堂 台北場','台北市信義區信義路五段1','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-27 17:22:30','2026-04-27 17:14:14','2026-04-27 17:22:30'),
('5','高雄市文化中心至德堂','台北市內湖區瑞湖街39號','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-27 17:22:33','2026-04-27 17:14:14','2026-04-27 17:22:33'),
('6','河岸留言西門紅樓展演館','台北市萬華區西寧南路177號)','西門紅樓，位於臺灣臺北市萬華區西門町，建築由近藤十郎設計，由八角樓與十字樓組成，日治時期原作為西門市場的室內市集；臺灣戰後時期八角樓作為演藝場所，今建物列臺北市定古蹟，作為文創場所與展演空間。','https://zh.wikipedia.org/wiki/%E8%A5%BF%E9%96%80%E7%B4%85%E6%A8%93','2026-04-27 17:22:35','2026-04-27 17:14:14','2026-04-27 17:22:35'),
('7','劍湖山世界主題樂園彩虹劇場','未提供','劍湖山世界 是位於臺灣雲林縣古坑鄉永光村劍湖附近的主題樂園，通稱劍湖山，綜合「休閒、遊樂、文化、科技」四大功能。園區佔地面積60多公頃，主要大型熱門活動常見為痛車，為嘉義耐斯企業旗下之大型遊樂園。和義大世界、六福村、九族文化村並稱臺灣遊樂園的「一三六九」。','https://zh.wikipedia.org/wiki/%E5%8A%8D%E6%B9%96%E5%B1%B1%E4%B8%96%E7%95%8C','2026-04-27 17:22:38','2026-04-27 17:14:14','2026-04-27 17:22:38'),
('9','衛武營國家藝術文化中心表演廳','未提供','衛武營國家藝術文化中心 全銜國家表演藝術中心衛武營國家藝術文化中心。位於臺灣高雄市鳳山區，衛武營都會公園東北側。是臺灣規模最大的文化設施、全球最大單一屋頂綜合劇院，也是南臺灣第一座國家級表演藝術場館，由衛武營藝術文化中心籌備處負責籌備規劃興建，完工後納入國家表演藝術中心，成為該中心轄下場館。','https://zh.wikipedia.org/wiki/%E8%A1%9B%E6%AD%A6%E7%87%9F%E5%9C%8B%E5%AE%B6%E8%97%9D%E8%A1%93%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-27 17:22:41','2026-04-27 17:14:14','2026-04-27 17:22:41'),
('10','高雄市文化中心至德堂','未提供','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-27 17:22:43','2026-04-27 17:14:14','2026-04-27 17:22:43'),
('11','臺北市政大樓親子劇場','未提供','臺北燈節 是臺北市政府於1997年開始主辦的臺灣元宵節燈節，首屆主燈於仁愛圓環，到2001年因中華民國交通部觀光局主辦的臺北燈會改為臺灣燈會並移師高雄市舉辦，臺北燈節場地移至中正紀念堂擴大舉辦。2005年主燈首次移置於臺北市市政大樓，而自2007年起地點則不固定於中正紀念堂原址、改至國立國父紀念館及臺北市市政大樓周邊舉辦，而自2013年地點則不固定於國父紀念館、地點改在花博公園圓山園區及美術園區。2017年起為活絡台北市西區的發展而改在熱鬧的西門町商圈。2021年擴大活動並首度移到萬華車站廣場、龍山寺、剝皮寮、青山宮、艋舺大道、康定路、西園路、華西街與廣州街等五大夜市舉辦，因COVID-19疫情影響將展期改在聖誕節。2022年為挽…','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8C%97%E7%87%88%E7%AF%80','2026-04-27 17:22:46','2026-04-27 17:14:14','2026-04-27 17:22:46'),
('12','台北國際會議中心大會堂','未提供','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-27 17:22:48','2026-04-27 17:14:14','2026-04-27 17:22:48'),
('14','嘉義縣表演藝術中心演藝廳','未提供','嘉義縣表演藝術中心（原稱民雄演藝廳）位於嘉義縣民雄鄉。園區佔地6.6公頃，從1995年起開始規劃，2005年年初完工，於4月22、23日啟用首演雲門舞集《紅樓夢》，5月10日正式營運管理。','https://zh.wikipedia.org/wiki/%E5%98%89%E7%BE%A9%E7%B8%A3%E8%A1%A8%E6%BC%94%E8%97%9D%E8%A1%93%E4%B8%AD%E5%BF%83','2026-04-27 17:22:50','2026-04-27 17:14:14','2026-04-27 17:22:50'),
('15','高雄流行音樂中心 海音館','803高雄市鹽埕區真愛路1號','高雄流行音樂中心，為高雄市政府文化局轄下的表演場館暨行政法人，原興建計畫名稱海洋文化及流行音樂中心，基地位於高雄港11-15號碼頭（真愛碼頭、光榮碼頭及苓雅寮車場），占地約11.89公頃，於2021年正式啟用。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E6%B5%81%E8%A1%8C%E9%9F%B3%E6%A8%82%E4%B8%AD%E5%BF%83','2026-04-27 17:22:53','2026-04-27 17:14:14','2026-04-27 17:22:53'),
('16','高雄市文化中心至善廳','802高雄市苓雅區五福一路67號','高雄市文化中心（舊名高雄市立中正文化中心）是位於高雄市苓雅區五福一路的一座大型表演展覽場地，佔地約13甲餘（約12.6公頃），建築形式為有中式建築特徵的粗野主義建築，在國家兩廳院落成啟用前，曾為台灣最大的現代化演藝廳。此文化中心同時也是高雄市政府文化局的辦公地點。','https://zh.wikipedia.org/wiki/%E9%AB%98%E9%9B%84%E5%B8%82%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-27 17:22:55','2026-04-27 17:14:14','2026-04-27 17:22:55'),
('17','台中中興大學惠蓀堂','未提供','費玉清（1955年7月17日—），本名張彦亭，外號小哥，小名亭亭，出身臺灣臺北，臺灣男歌手、主持人，以其華語、臺語流行歌曲演唱及綜藝節目主持表現等，在當代華語世界廣為人知。他在2019年舉行告別演出，後於2020年初完成合約工作後宣布自演藝事業退休。他是前歌手費貞綾及藝人張菲的弟弟。','https://zh.wikipedia.org/wiki/%E8%B2%BB%E7%8E%89%E6%B8%85','2026-04-27 17:22:57','2026-04-27 17:14:14','2026-04-27 17:22:57'),
('19','台北國際會議中心大會堂','台北市信義區信義路五段1號)','台北國際會議中心 位在臺灣臺北市信義計畫區。1984年12月27日，行政院會議核可交通部送審之《興建台北國際會議中心可行性研究報告》；1986年6月TICC動工興建，1989年11月完工；1989年12月4日，在「第十二屆亞洲大洋洲婦產科醫學會議」進入此建築、成為第一個在此處進行的國際會議的同時，也宣告正式啟用；最終，1990年1月8日，TICC成為台北世界貿易中心四合一建築範疇。','https://zh.wikipedia.org/wiki/%E5%8F%B0%E5%8C%97%E5%9C%8B%E9%9A%9B%E6%9C%83%E8%AD%B0%E4%B8%AD%E5%BF%83','2026-04-27 17:22:59','2026-04-27 17:14:14','2026-04-27 17:22:59'),
('20','臺南文化中心演藝廳 臺南場','台北市士林區文林路751號)','臺南文化中心是臺南市政府文化局永華文化中心管理科所轄之藝文場館，位於臺南市東區，鄰近巴克禮紀念公園與台糖長榮酒店，昔日為竹溪流經之地。此處經常舉行各種藝文活動，是臺南市民的休閒去處之一。開放時間為週三到週日09:00~17:00，週一週二休館。此外，該文化中心是臺灣各縣市唯一獲得建築金牌獎的文化中心，也是最早建立義務服務人員自治制度與推展家庭日服務的文化中心。與新營文化中心並列臺南兩大文化中心。','https://zh.wikipedia.org/wiki/%E8%87%BA%E5%8D%97%E6%96%87%E5%8C%96%E4%B8%AD%E5%BF%83','2026-04-27 17:23:02','2026-04-27 17:14:14','2026-04-27 17:23:02'),
('21','嘉義縣表演藝術中心演藝廳','屏東縣屏東市和平路427號','嘉義縣表演藝術中心（原稱民雄演藝廳）位於嘉義縣民雄鄉。園區佔地6.6公頃，從1995年起開始規劃，2005年年初完工，於4月22、23日啟用首演雲門舞集《紅樓夢》，5月10日正式營運管理。','https://zh.wikipedia.org/wiki/%E5%98%89%E7%BE%A9%E7%B8%A3%E8%A1%A8%E6%BC%94%E8%97%9D%E8%A1%93%E4%B8%AD%E5%BF%83','2026-04-27 17:23:04','2026-04-27 17:14:14','2026-04-27 17:23:04'),
('23','Legacy Taipei 音樂展演空間','台北市八德路一段1號 台北華山創意園區 中五館','詹雯婷（1981年8月27日—），臺灣創作女歌手。出道時以飛（或者稱飛兒）之藝名，擔任飛兒樂團主唱。2004年以經典電視劇《鬥魚》片尾曲〈Lydia〉知名，隔年獲第16屆金曲獎最佳新人獎。2018年10月詹雯婷宣布加盟亞神音樂，以本名繼續演藝活動。','https://zh.wikipedia.org/wiki/%E8%A9%B9%E9%9B%AF%E5%A9%B7','2026-04-27 17:23:05','2026-04-27 17:14:14','2026-04-27 17:23:05'),
('24','音浪塔四樓常設展','未提供','江西省美术馆，馆址初名毛泽东思想胜利万岁馆，俗称万岁馆，位于中国江西省南昌市八一广场西侧，是一家集展览、收藏、研究、教育等功能的公益性美术馆。','https://zh.wikipedia.org/wiki/%E6%B1%9F%E8%A5%BF%E7%9C%81%E7%BE%8E%E6%9C%AF%E9%A6%86','2026-04-27 17:23:08','2026-04-27 17:14:14','2026-04-27 17:23:08'),
('25','迴響音樂展演空間','未提供','TFAP來自台灣的台北，2019年成立，是以貝斯、鼓、吉他為主要編制的後搖滾樂團，於2020年10月發行首張EP《The Fog Talks to Me》。是第一屆以後搖滾為主的「秋波音樂節」的主要推手。','https://zh.wikipedia.org/wiki/TFAP','2026-04-27 17:23:10','2026-04-27 17:14:14','2026-04-27 17:23:10'),
('26','Revolver','未提供','《左轮手枪》 是英國搖滾樂團披头士的第七張录音室專輯，音樂製作人乔治·马丁。該專輯由EMI旗下Parlophone唱片於1966年8月5日在英国发行，三天之後於美國发行。這張專輯標誌著樂團從1965年的《Rubber Soul》專輯更進一步，更專注於录音室音樂的創新與製作，一年後於《比伯軍曹寂寞芳心俱樂部》專輯達到頂峰。','https://zh.wikipedia.org/wiki/%E5%B7%A6%E8%BD%AE%E6%89%8B%E6%9E%AA_(%E6%8A%AB%E5%A4%B4%E5%A3%AB%E4%B8%93%E8%BE%91)','2026-04-27 17:23:13','2026-04-27 17:14:14','2026-04-27 17:23:13'),
