-- BASE TABLE `event_artists`
CREATE TABLE "event_artists" (
  "event_id" bigint unsigned NOT NULL,
  "artist_id" bigint unsigned NOT NULL,
  "role_name" varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main',
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("event_id","artist_id"),
  KEY "fk_event_artists_artist" ("artist_id"),
  CONSTRAINT "fk_event_artists_artist" FOREIGN KEY ("artist_id") REFERENCES "artists" ("artist_id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "fk_event_artists_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE ON UPDATE CASCADE
);

-- BASE TABLE `event_schedules`
CREATE TABLE "event_schedules" (
  "schedule_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "performance_date" date DEFAULT NULL,
  "start_time" time DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "door_open_time" time DEFAULT NULL,
  "venue_notes" varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("schedule_id"),
  KEY "fk_es_event" ("event_id"),
  CONSTRAINT "fk_es_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);

-- BASE TABLE `event_segments`
CREATE TABLE "event_segments" (
  "event_id" bigint unsigned NOT NULL,
  "event_name" varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  "event_type" varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  "price_band" varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  "sale_status" varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  "confidence_score" decimal(4,2) NOT NULL,
  "rule_trace" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("event_id"),
  CONSTRAINT "fk_event_segments_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);

-- BASE TABLE `events`
CREATE TABLE "events" (
  "event_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_id" bigint unsigned DEFAULT NULL,
  "來源網站" text COLLATE utf8mb4_unicode_ci,
  "活動名稱" text COLLATE utf8mb4_unicode_ci,
  "藝人" text COLLATE utf8mb4_unicode_ci,
  "搶票時間" text COLLATE utf8mb4_unicode_ci,
  "活動時間" text COLLATE utf8mb4_unicode_ci,
  "活動地點" text COLLATE utf8mb4_unicode_ci,
  "活動地址" text COLLATE utf8mb4_unicode_ci,
  "票價" text COLLATE utf8mb4_unicode_ci,
  "票種" text COLLATE utf8mb4_unicode_ci,
  "網址" text COLLATE utf8mb4_unicode_ci,
  "爬取時間" text COLLATE utf8mb4_unicode_ci,
  "資料來源檔" text COLLATE utf8mb4_unicode_ci,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("event_id"),
  KEY "fk_events_venue" ("venue_id"),
  KEY "idx_events_source" ("來源網站"(64)),
  CONSTRAINT "fk_events_venue" FOREIGN KEY ("venue_id") REFERENCES "venues" ("venue_id") ON DELETE SET NULL ON UPDATE CASCADE
);
