('399','348','遠大售票 TicketPlus','NANA MIZUKI LIVE VISION 2025-2026+ in TAIPEI','NANA MIZUKI LIVE VISION 2025-2026+ in TAIPEI','※ 本活動為實名制售票，為保障您的權益，務必詳細閱讀頁面相關規定後再請進行購買。 若信用卡刷卡付款失敗，會將刷卡失敗的訂單，陸續轉為【ATM虛擬帳號付款】，屆時請依"我的訂單"顯示之「銀行帳號」、「銀行代碼」於「匯款期限」內完成付款，系統將以款項實際入帳時間為準，請於繳費後一小時至"我的訂單"確認，若訂單付款狀態顯示為「待繳費」，須等待銀行回傳付款狀態；若逾期未付款，系統收到銀行回傳付款狀態後將自動取消該筆訂單並顯示「付款失敗」，會員帳號之購票額度將於訂單取消之後釋出，各家銀行轉帳入帳時間不同，請盡早繳款以保障您的權益。 / 🎫 售票｜Ticket Plus 全場實名售票 / 6.實名制票券的參加者「證件姓名」、「證件號碼」如填寫有誤將不受理任何形式之資料變更申請，僅接受於退票期限內申請退票，請務必確認實名制資料無誤後再進行結帳，如因資料錯誤無法入場，主辦單位及遠大售票概不負責。 / • 請勿親送，收件地址現場無法受理 (為避免爭議，必須透過掛號第三方郵寄系統配送及簽收）。收件時間為週一至週五上午十點至下午六點，適逢國定假日暫停服務。 • 一旦申請退票後將無法取消退票申請，務必於退票前確認。 • 申請退票5個工作天後，請於"我的訂單"查詢訂單中的退票資訊欄位，該會員帳號購買額度須在退票資訊顯示後才可再次購買，若無變動，請務必來電或來信確認 Ticket Plus遠大售票系統 是否有收到退票申請。退款作業將由Ticket Plus遠大售票系統 收到退票申請起計算，約20個工作天內完成。','2026.04.11（六）17:30 ／ 2026.04.12（日）16:00 ／ 2026/03/29 (日) 12:00 ／ 2026.04.04（六）12:00','台北國際會議中心','TICC','未提供','未提供','https://ticketplus.com.tw/activity/472d71cb36cdfa5e483299bf1ca96c4e','2026-04-06 01:32:04','ticketplus_activities.json','2026-04-27 17:14:15');

-- BASE TABLE `sales_channels`
CREATE TABLE "sales_channels" (
  "channel_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "platform" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "channel_type" varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "start_date" date DEFAULT NULL,
  "start_time" time DEFAULT NULL,
  "end_date" date DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "sales_status" varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "notes" text COLLATE utf8mb4_unicode_ci,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("channel_id"),
  KEY "fk_sc_event" ("event_id"),
  CONSTRAINT "fk_sc_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);
