('398','398','遠大售票 TicketPlus','general',NULL,'11:00:00',NULL,NULL,'待開賣','憑藉獨特嗓音與過人創作才華、在日本樂壇掀起旋風的 Z 世代創作歌手 Leina，正式宣布將於 2026 年 5 月展開台北首場個人演唱會 Leina Live Tour 2026 "Jellyfish" in Taipei！這顆樂壇耀眼新星將於 5 月 2 日在台北三創 CLAPPER STUDIO 震撼登場，門票預計於 3 月 21 日於遠大售票系統正式開賣。 / 售票時間： 2026 年 3 月 21 日 (六) 11:00 AM / 售票系統： Ticket Plus 遠大售票系統 / ＊本次演出站位區入場順序將依售票系統上「位置」之號碼為準。（票面上請以「座位」之號碼為準），詳細整隊、入場資訊請留意後續主辦粉絲專頁相關公告。','2026-05-18 15:02:03'),
('399','399','遠大售票 TicketPlus','general',NULL,NULL,NULL,NULL,'販售中/未明','※ 本活動為實名制售票，為保障您的權益，務必詳細閱讀頁面相關規定後再請進行購買。 若信用卡刷卡付款失敗，會將刷卡失敗的訂單，陸續轉為【ATM虛擬帳號付款】，屆時請依"我的訂單"顯示之「銀行帳號」、「銀行代碼」於「匯款期限」內完成付款，系統將以款項實際入帳時間為準，請於繳費後一小時至"我的訂單"確認，若訂單付款狀態顯示為「待繳費」，須等待銀行回傳付款狀態；若逾期未付款，系統收到銀行回傳付款狀態後將自動取消該筆訂單並顯示「付款失敗」，會員帳號之購票額度將於訂單取消之後釋出，各家銀行轉帳入帳時間不同，請盡早繳款以保障您的權益。 / 🎫 售票｜Ticket Plus 全場實名售票 / 6.實名制票券的參加者「證件姓名」、「證件號碼」如填寫有誤將不受理任何形式之資料變更申請，僅接受於退票期限內申請退票，請務必確認實名制資料無誤後再進行結帳，如因資料錯誤無法入場，主辦單位及遠大售票概不負責。 / • 請勿親送，收件地址現場無法受理 (為避免爭議，必須透過掛號第三方郵寄系統配送及簽收）。收件時間為週一至週五上午十點至下午六點，適逢國定假日暫停服務。 • 一旦申請退票後將無法取消退票申請，務必於退票前確認。 • 申請退票5個工作天後，請於"我的訂單"查詢訂單中的退票資訊欄位，該會員帳號購買額度須在退票資訊顯示後才可再次購買，若無變動，請務必來電或來信確認 Ticket Plus遠大售票系統 是否有收到退票申請。退款作業將由Ticket Plus遠大售票系統 收到退票申請起計算，約20個工作天內完成。','2026-05-18 15:02:03');

-- BASE TABLE `ticket_pricing`
CREATE TABLE "ticket_pricing" (
  "price_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "event_id" bigint unsigned NOT NULL,
  "tier_name" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "price_amount" decimal(10,0) DEFAULT NULL,
  "max_quantity" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("price_id"),
  KEY "fk_tp_event" ("event_id"),
  CONSTRAINT "fk_tp_event" FOREIGN KEY ("event_id") REFERENCES "events" ("event_id") ON DELETE CASCADE
);

-- BASE TABLE `venue_locations`
CREATE TABLE "venue_locations" (
  "location_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_id" bigint unsigned NOT NULL,
  "city" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "district" varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "street" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "postal_code" varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "venue_details" text COLLATE utf8mb4_unicode_ci,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("location_id"),
  KEY "fk_vl_venue" ("venue_id"),
  CONSTRAINT "fk_vl_venue" FOREIGN KEY ("venue_id") REFERENCES "venues" ("venue_id") ON DELETE CASCADE
);

-- BASE TABLE `venues`
CREATE TABLE "venues" (
  "venue_id" bigint unsigned NOT NULL AUTO_INCREMENT,
  "venue_name" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "venue_address" varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  "venue_intro" longtext COLLATE utf8mb4_unicode_ci,
  "intro_source_url" varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "intro_updated_at" datetime DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("venue_id"),
  UNIQUE KEY "uq_venue_name_addr" ("venue_name","venue_address")
);
